 e += [ell(100,250,120,60,'#DDEDE2',GREEN),ell(224,320,115,55,'#DDEDE2',GREEN),ell(605,240,95,95,'#DDEDE2',GREEN),ell(705,305,105,90,'#DDEDE2',GREEN),ell(182,110,78,70,'#F5DDBE',GOLD),ell(667,115,66,58,'#DDEDE2',GREEN),tx(70,95,120,70,'Flower',24),tx(765,100,200,90,'Small green\nflower',25),tx(80,510,370,40,'Narrow leaves',27,True),tx(565,510,380,40,'Broad leaves',27,True)]
 return vis('Identify by structure and position','Two simplified flowering plants have different leaf shapes and flower appearances, while both possess roots, stems, leaves and flowers. Colours alone do not define the part.',e)
