seedneed=vis('Starting from a seed is a different stage','A germinating seed can use stored food reserves. An established green plant needs light for sustained photosynthesis. Species differ in whether seeds need light to germinate.',[rect(45,70,420,370,'#FFF2DC',GOLD),ell(165,155,160,110,'#DDBB87',GOLD),line(235,265,210,295,GOLD,False,8),tx(75,90,370,55,'Germinating seed',29,True),tx(75,310,360,115,'Uses stored reserves.\nNeeds water, oxygen and\nsuitable temperature.',27),rect(535,70,420,370,'#E4F0E9',GREEN),line(725,315,725,195,GREEN,False,10),ell(645,215,80,50,'#DDEDE2',GREEN),ell(730,265,80,50,'#DDEDE2',GREEN),tx(560,90,365,55,'Established green plant',27,True),tx(560,340,365,85,'Needs light for sustained\nsugar-making.',27),tx(45,480,915,65,'Some seeds also need light to germinate; check the species.',26,True)])
d=base('build_growth_needs_clinic','The growth-needs clinic','Summer 1 • Judge growth with more than height',32,'Identify requirements for healthy plant growth and use height plus leaf evidence to evaluate a care claim.',[('requirement','Something needed for a process or life.'),('mineral nutrient','A substance needed for healthy growth.'),('germination','A seed beginning to grow.'),('evidence','Information used to judge a claim.')],['Name light, water, suitable warmth and minerals.','Include air and sufficient space in a care plan.','Use leaf condition as well as height.'],['Roots absorb water and mineral nutrients.','Green leaves make sugars using light.'],[('The tallest seedling must be healthiest.','A dark-grown seedling can elongate and become pale; height alone is insufficient.','Compare groups A and B using leaf condition.'),('More water and warmth always help.','Too much water or unsuitable heat can harm growth; suitable amounts depend on the plant.','Ask for appropriate, not maximum, provision.'),('Every seed needs exactly the same light to germinate.','Species differ; many use stored reserves before green growth is established.','Distinguish germination from sustained green growth.')],[SAPS,RHS,RHS_SEED])
d['safety']=['This is a paper evidence clinic; no plants are deliberately deprived or overheated.','For optional care observation, use adult-selected non-toxic plants, no tasting, and wash hands afterwards.']
