d['slides']=[slide('Opening',2,'Which plant needs a better care plan?',['Height is one clue.','Look for a second clue.'],'Introduce constructed records of matched young bean seedlings. Do not present this as the class’s actual experiment.'),slide('Retrieval',3,'Retrieve the inputs',['1. Where does water enter?','2. What do green leaves need to make sugars?','3. Are minerals the same as ready-made sugar?'],'1 roots. 2 light, water and carbon dioxide from air; light enough for the short prompt. 3 no.'),slide('I do',7,'I check the whole set of needs',['Light, water and minerals matter.','Use suitable warmth, air and space.','Requirements work together.'],'Think aloud: “Providing water does not make light unnecessary. I check each requirement. I ask what is suitable for this plant, rather than assuming more is always better.”',visual=needs),slide('I do',0,'I refuse to use height alone',['A is shorter and green.','B is taller and pale.','Both observations matter.'],'Shares I do time. Think aloud: “13 is greater than 8, but pale small leaves change my judgement. Dark-grown seedlings can become elongated; taller is not a general health score.” The examples show selected seedlings from the constructed groups.',visual=heighthealth),slide('I do',0,'I separate seed and green-plant stages',['Seeds can use stored reserves.','Established green growth needs light.'],'Shares I do time. Think aloud: “A seed starting in darkness does not prove that an established green plant can grow well indefinitely without light.” Seeds also differ in light requirements.',visual=seedneed),slide('We do',4,'The evidence clinic: compare A and B',['Read both height readings.','Read leaf condition.','Make a care judgement with a reason.'],'W1: B is taller but pale; A shows stronger evidence of healthy growth here. All seedlings started about 3 cm. Two plants per group are supplied; not enough for a universal conclusion.',table=table(['Group','Day 7 heights (cm)','Leaf evidence'],[[r[0],r[2],r[3]] for r in growthrows],'Constructed sample data: two seedlings per group; all started about 3 cm')),slide('We do',4,'Choose a repair that fits the condition',['C: too little water.','D: unsuitable cool conditions.','Name a useful care change.'],'W2: C adjust watering appropriately; D provide suitable warmth. Do not tell pupils to flood a pot or put a plant on a radiator. The cases stipulate the changed condition, not a general diagnosis from drooping alone.',reveal='Address the stated missing requirement; keep other needs suitable.'),slide('Hinge',3,'B is 13 cm and pale. A is 8 cm and green.',['Which claim uses both clues?'],'Correct second option. Return to leaf condition if height alone dominates.',options=opts([('B must be healthier because it is taller.',False,'Pale small leaves challenge that conclusion.'),('Height alone cannot establish which grows well.',True,'Leaf condition and suitable inputs also matter.'),('No green plant needs light.',False,'Sustained photosynthesis needs light energy.')]))]
d['interactive']=dict(title='Growth clinic: choose the relevant evidence',intro='Constructed matched-seedling cases. Predict, reveal the model and justify using more than one clue.',slideIndex=5,steps=[step('A has suitable light, water and minerals. Can air and temperature be ignored?',[('No',True,'Air and an appropriate temperature are also needed.'),('Yes',False,'Plant requirements work together.')],needs,'A care plan checks the whole set of needs and the particular species.'),step('B is taller but pale. Does its height prove it is healthier than A?',[('No',True,'Pale small leaves are important evidence.'),('Yes',False,'Height alone is not a general measure of healthy growth.')],heighthealth,'Compare the supplied heights and leaf condition. State the evidence, not a universal ranking.'),step('A seed starts growing in darkness. Does that show a green plant can live indefinitely without light?',[('No',True,'Initial stored reserves differ from sustained sugar-making.'),('Yes',False,'Germination and established green growth are different stages.')],seedneed,'Light requirements for germination also vary among species.')])
