 e=[tx(45,25,910,50,'Constructed group mean heights' if points and means else 'Plot B1: supplied dates and heights',29,True),tx(45,78,290,45,'Height (cm)',27),line(140,430,915,430,DARK,False,3),line(140,430,140,120,DARK,False,3)]
 for yval in [0,4,8,12]:
  yy=430-yval*25;e +=[line(135,yy,915,yy,'#D6DEE4',False,2),tx(75,yy-20,55,40,str(yval),25)]
 for day in DAYS:
  xx=160+day*70;e +=[line(xx,430,xx,440,DARK,False,2),tx(xx-50,445,110,40,str(day),25,False,align='center')]
