d['slides']=[slide('Opening',2,'A record should survive a change of observer',['Keep IDs, dates and units.','Use supplied evidence to see ten days.'],'State explicitly that animation steps through constructed records; no real plant grows ten days during this lesson.'),slide('Retrieval',3,'Retrieve the measurement rule',['1. Where does the height ruler start?','2. What unit is used?','3. Why keep plant IDs?'],'1 soil surface. 2 cm. 3 track the same plant over time and preserve repeats.'),slide('I do',7,'I set up the record before comparing',['Label the plant.','Record date and baseline.','Use the same height rule.'],'Think aloud: “I record B1, date, cm and 3 cm starting height. Later 11 cm does not mean 11 cm growth: 11 minus 3 is 8 cm.” Demonstrate one real baseline if ready, or use the labelled worked model.',visual=measureplant),slide('I do',0,'I read time before height',['Read the day first.','Compare values at the same day.','The intervals are not all equal.'],'Shares I do time. Think aloud: “Day 3 to day 7 is four days, not three. The graph gives that interval more width. At day 10 the means are 6 and 11 cm.” Mean is an optional summary, explained as total divided by three; core pupils read individual rows.',visual=growthplot()),slide('I do',0,'I preserve a missing observation',['Not measured is not zero.','Leave a gap and give the reason.'],'Shares I do time. Think aloud: “No one measured plant X, so I cannot write zero. I mark missing. Our supplied six-plant table happens to be complete.”',visual=recordcheck),slide('We do',4,'The timeline evidence desk',['Find B1 on day 0 and day 10.','Calculate its height change.','Check with another reader.'],'W1: B1 goes from 3 to 11 cm; increase 8 cm. Have a pupil choose the date before the other reads the value. Step the model only after predicting.',table=table(['Day','A1 height (cm)','B1 height (cm)'],[[str(day),str(a[0]),str(b[0])] for day,a,b in zip(DAYS,AV,BV)],'Constructed sample data; individual plants A1 and B1')),slide('We do',4,'Keep the differences visible',['B1, B2, B3 finish at 11, 12, 10 cm.','Should we change them to match?','Add the leaf-condition record.'],'W2: retain all three; natural variation is useful. At day 10 B plants are green with 5–6 leaves; A plants have 2–3 leaves and A3 slightly droops. Heights alone do not prove overall health or a universal best water amount.',reveal='Describe the pattern and its limits; keep every reading.'),slide('Hinge',3,'B1 starts at 3 cm and ends at 11 cm.',['What is its recorded height increase?'],'Correct second option. Use a difference bar or counted steps if needed.',options=opts([('11 cm',False,'That is the final height, not the change.'),('8 cm',True,'11 minus 3 equals 8 cm.'),('0 cm because one other plant was not measured',False,'B1 has both measurements; a separate missing value does not erase them.')]))]
