 e +=[line(240,390,240,170,'#B85865'),tx(375,195,190,115,'Dye can mark\nwater pathways.',26),tx(55,100,140,95,'Cut stem',25)]
 return vis('Follow a visible tracer','Two cut flower shoots stand in separate cups, one with coloured water and one with plain water. Dye can mark internal water routes in the shoot; neither shoot has roots. The plain-water cup is a comparison.',e)
